fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    // Pre-allocate a result vector with the same length as the input
    let mut result = Vec::with_capacity(s.len());

    // Iterate through each character, converting ASCII 'A'..='Z' to lowercase by adding 32,
    // otherwise leaving it unchanged.
    for &c in s.iter() {
        if c >= 'A' && c <= 'Z' {
            // Safe to cast to u32, add 32, and convert back to char
            let lower = std::char::from_u32(c as u32 + 32).unwrap();
            result.push(lower);
        } else {
            result.push(c);
        }
    }

    result
}

